import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Scratch-Variables.md","filePath":"manual-en/Scratch-Variables.md","lastUpdated":1785684581000}'),i={name:"manual-en/Scratch-Variables.md"};function o(n,e,c,h,l,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h4 id="_6-7-5-scratch-variables" tabindex="-1">6.7.5 Scratch Variables <a class="header-anchor" href="#_6-7-5-scratch-variables" aria-label="Permalink to &quot;6.7.5 Scratch Variables&quot;">​</a></h4><p>Most of the time, variables don’t retain their values between cases. Instead, either they’re being read from a data file or the active dataset, in which case they assume the value read, or, if created with <code>COMPUTE</code> or another transformation, they’re initialized to the system-missing value or to blanks, depending on type.</p><p>However, sometimes it’s useful to have a variable that keeps its value between cases. You can do this with <code>LEAVE</code> (see <a href="./LEAVE">LEAVE</a>), or you can use a <em>scratch variable</em>. Scratch variables are variables whose names begin with an octothorpe (‘#’).</p><p>Scratch variables have the same properties as variables left with <code>LEAVE</code>: they retain their values between cases, and for the first case they are initialized to 0 or blanks. They have the additional property that they are deleted before the execution of any procedure. For this reason, scratch variables can’t be used for analysis. To use a scratch variable in an analysis, use <code>COMPUTE</code> (see <a href="./COMPUTE">COMPUTE</a>) to copy its value into an ordinary variable, then use that ordinary variable in the analysis.</p>',4)])])}const u=a(i,[["render",o]]);export{p as __pageData,u as default};
